<?php
declare(strict_types=1);
require_once __DIR__.'/../../includes/auth.php';require_once __DIR__.'/../../config/db.php';requireModuleAccess('customer_orders');
$id=(int)($_GET['id']??0);$q=$conn->prepare("SELECT o.*,c.customer_name,c.phone,c.address,u.full_name creator,v.full_name validator FROM customer_sales_orders o JOIN customers c ON c.id=o.customer_id LEFT JOIN users u ON u.id=o.created_by LEFT JOIN users v ON v.id=o.validated_by WHERE o.id=?");$q->execute([$id]);$o=$q->fetch();if(!$o){http_response_code(404);exit('Order not found.');}
$q=$conn->prepare("SELECT i.*,p.product_name,p.unit FROM customer_sales_order_items i JOIN products p ON p.id=i.product_id WHERE i.order_id=? ORDER BY i.id");$q->execute([$id]);$items=$q->fetchAll();$currency=(string)($conn->query("SELECT setting_value FROM settings WHERE setting_key='currency' LIMIT 1")->fetchColumn()?:'KES');$flash=$_SESSION['customer_order_flash']??'';unset($_SESSION['customer_order_flash']);
require_once __DIR__.'/../../includes/header.php';require_once __DIR__.'/../../includes/sidebar.php';?>
<main class="content"><style>.ov-panel{max-width:1000px;margin:auto;background:#fff;border:1px solid #e2e8f0;border-radius:12px;padding:22px}.ov-head{display:flex;justify-content:space-between;gap:15px;flex-wrap:wrap}.ov-table{width:100%;border-collapse:collapse;margin-top:20px}.ov-table th,.ov-table td{padding:11px;border-bottom:1px solid #e5eaf0;text-align:left}.ov-num{text-align:right!important}.ov-btn{display:inline-block;padding:10px 14px;border:0;border-radius:7px;background:#174a7e;color:#fff;text-decoration:none;font-weight:750;cursor:pointer}.muted{color:#64748b}</style>
<div class="ov-panel"><?php if($flash):?><p><?=e($flash)?></p><?php endif;?><div class="ov-head"><div><h1>Sales Order <?=e($o['order_number'])?></h1><p class="muted"><?=e($o['customer_name'])?> · <?=e($o['phone']??'')?></p><p class="muted">Created <?=e($o['order_date'])?> by <?=e($o['creator']??'Staff')?> · Status: <strong><?=e($o['status'])?></strong></p></div><div><a class="ov-btn" href="index.php">Back to orders</a></div></div>
<table class="ov-table"><thead><tr><th>Product</th><th>Quantity</th><th>Unit price</th><th class="ov-num">Total</th></tr></thead><tbody><?php foreach($items as $it):?><tr><td><?=e($it['product_name'])?></td><td><?=e($it['entered_quantity'])?> <?=e($it['sale_unit'])?></td><td><?=e($currency)?> <?=number_format((float)$it['entered_unit_price'],2)?></td><td class="ov-num"><?=e($currency)?> <?=number_format((float)$it['subtotal'],2)?></td></tr><?php endforeach;?></tbody></table>
<div class="ov-num"><p>Subtotal: <?=e($currency)?> <?=number_format((float)$o['subtotal'],2)?></p><p>VAT: <?=e($currency)?> <?=number_format((float)$o['tax'],2)?></p><h2>Total: <?=e($currency)?> <?=number_format((float)$o['total_amount'],2)?></h2></div>
<?php if($o['status']==='Draft'&&hasModulePermission('customer_orders','edit')):?><form method="post" action="action.php" onsubmit="return confirm('Validate this order? Current stock availability will be checked.')"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=$id?>"><input type="hidden" name="action" value="validate"><button class="ov-btn">Validate Order</button></form><?php elseif($o['status']==='Validated'):?><p class="muted">Validated by <?=e($o['validator']??'Staff')?>. This order is waiting in Pending Invoices.</p><a class="ov-btn" href="pending.php">Go to Pending Invoices</a><?php elseif($o['status']==='Invoiced'):?><a class="ov-btn" target="_blank" href="invoice.php?id=<?=$id?>">Print confirmed invoice</a><?php endif;?>
</div></main><?php require_once __DIR__.'/../../includes/footer.php';?>